/* Inject the shared support-page enhancement layer
 * (shared/support/support-enhance.css + .js) into the generated
 * lessons/<id>/{family,student-help,teacher-notes}/ pages.
 *
 * Mirrors tools/inject-mobile-access.js: a single <link> before </head> and a
 * single <script defer> before </body>, each guarded by an idempotent sentinel
 * marker. Additive and print-safe — see shared/support/.
 *
 * Scope: ONLY lessons/<id>/{family,student-help,teacher-notes}/index.html.
 * These are regenerated by scripts/generate-lesson-support-pages.mjs without
 * shared assets, so re-run this injector after regenerating (same contract as
 * inject-mobile-access.js).
 *
 * Usage:
 *   node tools/inject-support-enhance.js            # inject (writes files)
 *   node tools/inject-support-enhance.js --dry-run  # report only
 *   node tools/inject-support-enhance.js --revert   # remove the injected blocks
 */
import { readdirSync, statSync, readFileSync, writeFileSync } from "fs";
import { join, dirname } from "path";
import { fileURLToPath } from "url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const LESSONS_DIR = join(ROOT, "lessons");
const SUBS = ["family", "student-help", "teacher-notes"];

const MARK = "support-enhance-injected";
const LINK_TAG =
  '<link rel="stylesheet" href="/shared/support/support-enhance.css">';
const SCRIPT_TAG =
  '<script src="/shared/support/support-enhance.js" defer></script>';
const BEGIN = `<!-- ${MARK}:begin (support-page enhancement — tools/inject-support-enhance.js) -->`;
const END = `<!-- ${MARK}:end -->`;

const args = new Set(process.argv.slice(2));
const DRY = args.has("--dry-run");
const REVERT = args.has("--revert");

const report = {
  scanned: 0,
  injected: 0,
  already: 0,
  reverted: 0,
  skippedNoTags: [],
};

function supportPages() {
  const out = [];
  let ids = [];
  try {
    ids = readdirSync(LESSONS_DIR);
  } catch {
    return out;
  }
  for (const id of ids) {
    for (const sub of SUBS) {
      const file = join(LESSONS_DIR, id, sub, "index.html");
      let st;
      try {
        st = statSync(file);
      } catch {
        continue;
      }
      if (st.isFile()) out.push(file);
    }
  }
  return out;
}

function revert(html) {
  const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const re = new RegExp(`\\s*${esc(BEGIN)}[\\s\\S]*?${esc(END)}`, "g");
  return html.replace(re, "");
}

function processFile(file) {
  report.scanned++;
  let html = readFileSync(file, "utf8");

  if (REVERT) {
    if (html.includes(`${MARK}:begin`)) {
      if (!DRY) writeFileSync(file, revert(html));
      report.reverted++;
    }
    return;
  }

  if (html.includes(`${MARK}:begin`)) {
    report.already++;
    return;
  }
  if (!/<\/head>/i.test(html) || !/<\/body>/i.test(html)) {
    report.skippedNoTags.push(file);
    return;
  }

  html = html.replace(
    /<\/head>/i,
    `  ${BEGIN}\n  ${LINK_TAG}\n  ${END}\n</head>`,
  );
  html = html.replace(
    /<\/body>/i,
    `  ${BEGIN}\n  ${SCRIPT_TAG}\n  ${END}\n</body>`,
  );
  if (!DRY) writeFileSync(file, html);
  report.injected++;
}

supportPages().forEach(processFile);

console.log(
  `Support-enhance injection ${DRY ? "(dry-run)" : ""}${REVERT ? " — revert" : ""}`,
);
console.log("  support pages scanned:", report.scanned);
if (REVERT) {
  console.log("  reverted             :", report.reverted);
} else {
  console.log("  injected             :", report.injected);
  console.log("  already injected     :", report.already);
  console.log("  skipped (no tags)    :", report.skippedNoTags.length);
}
